import type { Product, ProductProjection } from '@commercetools/platform-sdk';

/**
 * Reading a Product the way the engine reads a Product Projection.
 *
 * The Product API Extension hands over a full Product — master data split
 * into current and staged — while a catalog sweep reads Product Projections.
 * Flattening one into the other means there is a single matching engine
 * rather than two that have to agree.
 */
export function projectionFromProduct(
  product: Product,
  which: 'staged' | 'current' = 'staged'
): ProductProjection {
  const master = product.masterData;
  const data = which === 'staged' ? master.staged : master.current;

  return {
    ...data,
    id: product.id,
    version: product.version,
    key: product.key,
    createdAt: product.createdAt,
    lastModifiedAt: product.lastModifiedAt,
    productType: product.productType,
    taxCategory: product.taxCategory,
    state: product.state,
    reviewRatingStatistics: product.reviewRatingStatistics,
    priceMode: product.priceMode,
    published: master.published,
    hasStagedChanges: master.hasStagedChanges,
  } as ProductProjection;
}

/**
 * Whether a category change should land on the staged projection alone.
 *
 * The answer mirrors what the merchandiser was already doing. An unpublished
 * product has nothing but staged data. A product carrying staged changes is
 * mid-edit, and pushing a rule's category into `current` would publish part
 * of that edit early. Anything else is a published product in step with its
 * staged copy, so both move together and the storefront sees the assignment
 * without the connector publishing anything.
 */
export function stagedFlagFor(product: {
  published?: boolean;
  hasStagedChanges?: boolean;
}): boolean {
  if (!product.published) return true;
  if (product.hasStagedChanges) return true;
  return false;
}
